#!/usr/bin/env bash
set -euo pipefail

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd -P)"
launcher="$HOME/bin/spb"
link="$HOME/.local/bin/spb"

# Preserve commands owned by another installer or project.
if [[ -e "$launcher" || -L "$launcher" ]]; then
  if [[ ! -f "$launcher" ]] || ! grep -Eq \
    '^# (Generated by system-prompt-builder just install-dev|Run the editable checkout while keeping the caller)' \
    "$launcher"; then
    echo "Refusing to replace $launcher" >&2
    exit 1
  fi
fi
if [[ -e "$link" || -L "$link" ]]; then
  if [[ ! -L "$link" ]]; then
    echo "Refusing to replace $link" >&2
    exit 1
  fi
  target="$(readlink "$link")"
  if [[ "$target" != "$launcher" &&
        "$target" != */pipx/venvs/system-prompt-builder/bin/spb ]]; then
    echo "Refusing to replace $link -> $target" >&2
    exit 1
  fi
fi

command -v pipenv >/dev/null || { echo 'pipenv is required' >&2; exit 1; }
cd "$repo_root"
pipenv sync --dev
# Refresh editable distribution metadata when pyproject.toml changes.
pipenv run python -m pip install --no-deps --editable .

if command -v pipx >/dev/null && pipx list --short | grep -q '^system-prompt-builder '; then
  pipx uninstall system-prompt-builder
fi

mkdir -p "$HOME/bin" "$HOME/.local/bin"
temporary="$(mktemp "$HOME/bin/.spb.XXXXXXXX")"
trap 'rm -f "$temporary"' EXIT
printf -v quoted_pipfile '%q' "$repo_root/Pipfile"
{
  printf '#!/usr/bin/env bash\n'
  printf '# Generated by system-prompt-builder just install-dev.\n'
  printf 'export PIPENV_PIPFILE=%s\n' "$quoted_pipfile"
  printf 'exec pipenv run spb "$@"\n'
} > "$temporary"
chmod 755 "$temporary"
mv -f "$temporary" "$launcher"
rm -f "$link"
ln -s "$launcher" "$link"
echo "Installed development spb: $link -> $launcher"
echo "Ensure $HOME/.local/bin is on PATH."
